&-hero-slogan {
  --hero-slogan-surface-alpha: 0.24;

  width: 100%;
  position: relative;
  background: rgba(0, 0, 0, var(--hero-slogan-surface-alpha));
  backdrop-filter: blur(24px);
  -webkit-backdrop-filter: blur(24px);

  &__title {
    text-align: center;

    h2 {
      display: flex;
      flex-direction: column;
      align-items: center;
      gap: fluid(8, 16);
      line-height: 0.9;
    }

    .line {
      text-align: center;
    }
  }

  &__line {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: fluid(10, 18);
    .weak {
      opacity: 0.4;
    }
  }

  &__line.mask-target {
    display: block;

    > .masking-text {
      display: block;
      overflow: hidden;
    }

    > .masking-text > .masking-text__line {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: fluid(10, 18);
    }
  }

  &__keyword-shell {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: fluid(10, 14);
    color: var(--clr-white-100);
    white-space: nowrap;
  }

  &__bracket {
    color: color-mix(in srgb, var(--clr-white-100) 72%, transparent);
    font-weight: 400;
  }

  &__keyword-viewport {
    position: relative;
    display: inline-block;
    height: 0.98em;
    width: auto;
    flex: 0 0 auto;
    overflow: hidden;
    vertical-align: top;
    will-change: width;
  }

  &__keyword-track {
    display: flex;
    flex-direction: column;
    align-items: center;
    transform: translate3d(0, 0, 0);
    will-change: transform;
  }

  &__keyword {
    display: flex;
    align-items: center;
    justify-content: center;
    min-height: 0.98em;
    opacity: 0.4;
    filter: blur(8px);
    text-shadow: 0 0 0 rgba(255, 255, 255, 0);
    will-change: opacity, filter, text-shadow;
  }

